css:
.ss-posts{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.ss-post{display:flex;flex-direction:column;background:var(--card);border:1px solid var(--line);position:relative;transition:transform .28s cubic-bezier(.2,.7,.2,1),box-shadow .28s ease,border-color .28s ease}
/* Hover: the card lifts on a soft shadow, an accent rule draws in along its foot,
   the photo eases in, the title takes the accent and "Read more" steps forward.
   :focus-within gives a keyboard user the same card a mouse user sees. */
.ss-post::after{content:"";position:absolute;left:-1px;right:-1px;bottom:-1px;height:3px;background:var(--accent);transform:scaleX(0);transform-origin:left;transition:transform .35s cubic-bezier(.2,.7,.2,1);pointer-events:none}
.ss-post:hover,.ss-post:focus-within{transform:translateY(-6px);border-color:color-mix(in srgb,var(--accent) 45%,var(--line));box-shadow:0 22px 44px -22px color-mix(in srgb,var(--ink) 45%,transparent),0 6px 14px -8px color-mix(in srgb,var(--ink) 20%,transparent)}
.ss-post:hover::after,.ss-post:focus-within::after{transform:scaleX(1)}
.ss-post__media img{transition:transform .6s cubic-bezier(.2,.7,.2,1)}
.ss-post:hover .ss-post__media img,.ss-post:focus-within .ss-post__media img{transform:scale(1.06)}
.ss-post:hover .ss-post__title a,.ss-post:focus-within .ss-post__title a{color:var(--accent)}
.ss-post__more{align-self:flex-start;transition:transform .28s cubic-bezier(.2,.7,.2,1)}
.ss-post:hover .ss-post__more,.ss-post:focus-within .ss-post__more{transform:translateX(5px)}
/* The whole card is the link: the title's link is stretched over it, so the
   photo, the excerpt and the gutters all click through to the post. */
.ss-post__title a::before{content:"";position:absolute;inset:0;z-index:1}
.ss-post__title a:focus-visible{outline:none}
.ss-post:has(.ss-post__title a:focus-visible){outline:2px solid var(--accent);outline-offset:3px}
@media (prefers-reduced-motion:reduce){.ss-post,.ss-post::after,.ss-post__media img,.ss-post__more{transition:none}.ss-post:hover,.ss-post:focus-within{transform:none}.ss-post:hover .ss-post__media img,.ss-post:focus-within .ss-post__media img{transform:none}.ss-post:hover .ss-post__more,.ss-post:focus-within .ss-post__more{transform:none}}
.ss-post[hidden]{display:none}
.ss-post__media{display:block;position:relative;height:190px;background:var(--paper);overflow:hidden}
.ss-post__media img,.ss-post__media .bz-photo{width:100%;height:100%;object-fit:cover;display:block}
.ss-post__body{display:flex;flex-direction:column;flex:1;padding:24px 22px 26px}
.ss-post__meta{display:flex;gap:10px;align-items:baseline;flex-wrap:wrap;margin-bottom:12px}
.ss-post__topic{font:700 10px/1.3 var(--font-body);letter-spacing:.14em;color:var(--accent)}
.ss-post__date{font-size:12px;color:var(--muted)}
.ss-post__title{font:800 19px/1.3 var(--font-heading);margin:0 0 12px}
.ss-post__title a{color:var(--ink);text-decoration:none}
.ss-post__title a:hover{color:var(--accent)}
.ss-post__excerpt{font-size:14px;line-height:1.7;color:var(--body-text);margin:0 0 18px}
.ss-post__more{font-size:14px;font-weight:700;color:var(--accent);text-decoration:none;margin-top:auto}
.ss-post__more:hover{text-decoration:underline}
.ss-posts__empty{font-size:15px;color:var(--muted);border-top:1px solid var(--line);padding-top:22px;margin:24px 0 0}
.ss-posts__empty[hidden]{display:none}
@media (max-width:1100px){.ss-posts{grid-template-columns:repeat(2,1fr)}}
@media (max-width:640px){.ss-posts{grid-template-columns:1fr}}
.ss-post__ph{display:flex;align-items:center;justify-content:center;width:100%;height:100%;background:var(--paper);border:1px dashed var(--line);box-sizing:border-box}
.ss-post__ph-l{font:700 10px/1 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
.ss-post__media:hover .ss-post__ph{border-color:var(--muted)}
@media (max-width:640px){.ss-post__topic,.ss-post__ph-l{font-size:12px}
.ss-post__more{padding-block:10px;margin-block:-10px}}
